import json
CHAR = "Flat 2D cartoon: a simple white character with a big round head, a small soft body, noodle arms with simple four-finger hands and short legs with rounded feet, thick smooth black (#000000) outlines of even weight, about 2 % of the head width thick, flat white fill (#FEFDFD) with a very soft pale-grey shade (#EDEBEB) on the left side of the head and body, the round head is wider than the body and about 0.38 of the full body height, small solid black vertical oval eyes about one sixth of the head width tall, simple curved black eyebrows, no nose, no hair, no clothes, a pink tongue (#FC8D90) only when the mouth is open. Clean vector-like linework, flat colours, no texture, no text, no border."
OBJ = "Flat 2D cartoon in the same drawing style: bold clean thick smooth black outlines of even weight, flat colours with one simple soft shade, clean vector-like linework, simple shapes, no texture, no text, no border, no characters."
def KEY(c='green'):
    col = 'pure green (#00FF00)' if c == 'green' else 'pure magenta (#FF00FF)'
    return f"Isolated on a perfectly flat, uniform, solid {col} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
BG = "Flat 2D cartoon background in the same drawing style: big simple flat-colour shapes, thick smooth black outlines only on the main shapes, no texture, no text, no labels, no arrows, no characters, calm and simple so a character reads clearly on top of it. Clean open ground in the lower middle where the character will stand; horizon at about 60 % of the height."
TWO = "Two DIFFERENT poses of the same character side by side with a wide gap between them, both full body, bold clean thick outlines. "
GIRL = " This character is a little girl: exactly the same simple white character, but a bit smaller and with one small red (#E8322E) bow on top of the head - nothing else added, no hair, no clothes."
DAD = " This character is a dad: exactly the same simple white character, a bit taller, wearing only a small yellow straw sun hat and round black sunglasses pushed up on the forehead - nothing else added, no hair, no clothes."
P = {
 'hero': ("2:3", "Full body, three-quarter view facing to the right, standing and looking to the right with a puzzled curious face: one eyebrow raised, small open mouth, one hand on the RIGHT side of the image pointing forward to the right. Whole body in frame with a margin. Bold clean thick outlines. " + CHAR + GIRL + " " + KEY()),
 'girl2': ("3:2", TWO + "LEFT copy: facing the viewer, shouting a warning: both arms raised high and waving, eyebrows tilted up in the middle, wide eyes, mouth wide open with the pink tongue showing. RIGHT copy: side view running fast to the LEFT, one arm stretched forward to the left, legs in a big running stride, scared determined face. Whole bodies in frame with a margin. " + CHAR + GIRL + " " + KEY()),
 'dad2': ("3:2", TWO + "LEFT copy: lying back relaxed in a simple striped red-and-white wooden beach deck chair, facing the viewer, one hand waving dismissively, half-closed bored eyes, small smug smile. RIGHT copy (no chair): side view running fast to the LEFT, holding the straw hat on the head with one hand, terrified face: eyebrows tilted up, wide eyes, mouth wide open. Whole bodies in frame with a margin. " + CHAR + DAD + " " + KEY()),
 'guard': ("2:3", "Full body, facing the viewer, a beach guard: the same simple white character wearing only a small blue cap, blowing a silver whistle held in the mouth, cheeks puffed, one arm on the LEFT side of the image pointing far to the left, eyebrows lowered and serious. Whole body in frame with a margin. Bold clean thick outlines. " + CHAR + " " + KEY()),
 'tourists2': ("3:2", "Two groups side by side with a wide gap between them, bold clean thick outlines. LEFT group: three of the same simple white characters standing close together facing to the RIGHT, frozen and staring with blank surprised faces and small round mouths; the front one holds a pink ice cream cone, the middle one holds a small black camera, the back one wears a small blue swim ring around the waist. RIGHT group: the same three characters running fast to the LEFT in panic, arms flailing, terrified open mouths, the ice cream cone flying up out of the hand. Whole bodies in frame with a margin. " + CHAR + " " + KEY()),
 'hotel': ("2:3", "One small cheerful beach hotel building seen from the front: a white four-storey block with a flat roof, a row of blue balconies with railings on every floor, a big glass front door at the bottom, an orange sign shape on the roof with no letters, two small palm trees beside it. Bold clean thick outlines. " + OBJ + " " + KEY('magenta')),
 'wave': ("3:2", "One giant cartoon ocean wave seen from the side, rising tall and curling over to the LEFT like a big hook, deep blue body getting lighter toward the top, a thick white foam crest along the curl, a flat bottom edge. No face, no water around it, no sky. Bold clean thick outlines. " + OBJ + " " + KEY('magenta')),
 'bg': ("2:3", "A sunny tropical beach seen from the sand, vertical picture: a clear warm light-blue sky with two small flat white clouds in the top half, a straight sea horizon at 52 % of the height, a calm turquoise sea band below it, and pale golden sand filling the lower 35 % of the picture with a few small shells; one leaning palm tree at the very left edge. No people, no buildings, no boats, no sun. " + BG.replace(" Clean open ground in the lower middle where the character will stand; horizon at about 60 % of the height.", " Clean open sand in the lower middle.")),
}
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# tsunami-girl - picture prompts (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, no references)\n\n')
    for k, (ar, p) in P.items(): f.write(f'## {k} ({ar})\n{p}\n\n')
print('ok', len(P))
